import Foundation

// An enum with a `String` raw value is stored as that string ("keep"), like a TypeScript
// string union `"keep" | "review" | "reject"`. `Codable` lets it be encoded/decoded to JSON
// (a typed `JSON.stringify` / `JSON.parse`, generated by the compiler).

/// The AI proposal for a photo. It only proposes: nothing is ever deleted automatically.
enum CullingVerdict: String, Codable, Sendable, CaseIterable {
    case keep, review, reject
    /// Value written by a future version of the app and unknown to this one.
    case unknown

    /// A custom decoder: an unrecognised value becomes `.unknown` instead of failing.
    init(from decoder: Decoder) throws {
        let rawValue = try decoder.singleValueContainer().decode(String.self)
        self = CullingVerdict(rawValue: rawValue) ?? .unknown
    }

    /// Higher = more severe. The verdict of a photo is the most severe of its reasons.
    var severity: Int {
        switch self {
        case .keep: 0
        case .review, .unknown: 1
        case .reject: 2
        }
    }

    /// Text shown to the user.
    var label: String {
        switch self {
        case .keep: String(localized: "Garder")
        case .review: String(localized: "À revoir")
        case .reject: String(localized: "Rejeter")
        case .unknown: String(localized: "Inconnu")
        }
    }
}

enum FrameSide: String, Codable, Sendable {
    case left, right, top, bottom
}

/// Why a photo got its verdict. Stored as a code plus values; the French sentence is built
/// when displayed (`message`), so it stays localizable and follows the user's number format.
struct CullingReason: Codable, Sendable, Equatable {
    enum Kind: String, Codable, Sendable {
        case blurry, slightlyBlurry
        case subjectCut, subjectTight
        case overexposed, slightlyOverexposed, underexposed, nearlyBlack
        case eyesClosed
        case lowAesthetics, utility
        case burstRunnerUp, burstLoser, bestOfBurst
        case noIssue
        case analysisFailed
        case unknown

        init(from decoder: Decoder) throws {
            let rawValue = try decoder.singleValueContainer().decode(String.self)
            self = Kind(rawValue: rawValue) ?? .unknown
        }
    }

    var kind: Kind
    var verdict: CullingVerdict
    /// Measured value shown in the message: sharpness, margin or share of pixels (0…1), score.
    var value: Double?
    /// Threshold the value was compared to.
    var threshold: Double?
    /// Blur: measured on the subject (true) or on the whole image (false).
    var onSubject: Bool?
    /// Blur: share of the gallery at most as sharp as this photo (0.05 = among the 5 % least sharp).
    /// Nil for a small gallery, judged on the score alone, and for reasons stored by older versions.
    var galleryShare: Double?
    /// Framing: the image border closest to the subject.
    var side: FrameSide?
    /// Number of faces with closed eyes.
    var count: Int?
    /// Bursts: path of the best photo of the burst.
    var bestPhoto: String?

    // Parameters with a default value can be left out when calling the initializer
    // (like optional properties in a TypeScript object literal).
    init(
        kind: Kind,
        verdict: CullingVerdict,
        value: Double? = nil,
        threshold: Double? = nil,
        onSubject: Bool? = nil,
        galleryShare: Double? = nil,
        side: FrameSide? = nil,
        count: Int? = nil,
        bestPhoto: String? = nil
    ) {
        self.kind = kind
        self.verdict = verdict
        self.value = value
        self.threshold = threshold
        self.onSubject = onSubject
        self.galleryShare = galleryShare
        self.side = side
        self.count = count
        self.bestPhoto = bestPhoto
    }
}

extension CullingReason {
    /// The sentence shown to the user. `locale` only changes how numbers are written ("4,0 %").
    func message(locale: Locale = .current) -> String {
        let value = value ?? 0, threshold = threshold ?? 0
        let best = bestPhoto ?? "—"
        switch kind {
        case .blurry:
            let measured = number(value, locale), limit = number(threshold, locale)
            if let galleryShare {
                let share = leastSharpShare(galleryShare, locale)
                return onSubject == true
                    ? String(localized: "Floue (netteté du sujet \(measured), parmi les \(share) les moins nettes)")
                    : String(localized: "Floue (netteté de l'image \(measured), parmi les \(share) les moins nettes)")
            }
            return onSubject == true
                ? String(localized: "Floue (netteté du sujet \(measured) < \(limit))")
                : String(localized: "Floue (netteté de l'image \(measured) < \(limit))")
        case .slightlyBlurry:
            let measured = number(value, locale), limit = number(threshold, locale)
            if let galleryShare {
                let share = leastSharpShare(galleryShare, locale)
                return onSubject == true
                    ? String(localized: "Légèrement floue (netteté du sujet \(measured), parmi les \(share) les moins nettes)")
                    : String(localized: "Légèrement floue (netteté de l'image \(measured), parmi les \(share) les moins nettes)")
            }
            return onSubject == true
                ? String(localized: "Légèrement floue (netteté du sujet \(measured) < \(limit))")
                : String(localized: "Légèrement floue (netteté de l'image \(measured) < \(limit))")
        case .subjectCut:
            switch side {
            case .left: return String(localized: "Sujet coupé par le bord gauche")
            case .right: return String(localized: "Sujet coupé par le bord droit")
            case .top: return String(localized: "Sujet coupé par le haut")
            case .bottom: return String(localized: "Sujet coupé par le bas")
            case nil: return String(localized: "Sujet coupé par un bord")
            }
        case .subjectTight:
            let margin = percent(value, locale, digits: 1)
            switch side {
            case .left: return String(localized: "Sujet collé au bord gauche (marge \(margin))")
            case .right: return String(localized: "Sujet collé au bord droit (marge \(margin))")
            case .top: return String(localized: "Sujet collé au bord du haut (marge \(margin))")
            case .bottom: return String(localized: "Sujet collé au bord du bas (marge \(margin))")
            case nil: return String(localized: "Sujet collé à un bord (marge \(margin))")
            }
        case .overexposed:
            return String(localized: "Très surexposée (\(percent(value, locale)) de pixels brûlés)")
        case .slightlyOverexposed:
            return String(localized: "Hautes lumières brûlées (\(percent(value, locale)) des pixels)")
        case .underexposed:
            return String(localized: "Sous-exposée (\(percent(value, locale)) de pixels noirs)")
        case .nearlyBlack:
            return String(localized: "Presque entièrement noire (\(percent(value, locale)) de pixels noirs)")
        case .eyesClosed:
            let faces = count ?? 1
            return faces == 1
                ? String(localized: "Yeux fermés (1 visage)")
                : String(localized: "Yeux fermés (\(faces) visages)")
        case .lowAesthetics:
            return String(localized: "Score esthétique faible (\(number(value, locale, digits: 2)))")
        case .utility:
            return String(localized: "Photo utilitaire (document, capture d'écran…)")
        case .burstRunnerUp:
            return String(localized: "Presque aussi bonne que \(best), la meilleure de la rafale")
        case .burstLoser:
            return String(localized: "Moins bonne de la rafale (meilleure : \(best))")
        case .bestOfBurst:
            return String(localized: "Meilleure photo de la rafale")
        case .noIssue:
            return String(localized: "Aucun défaut détecté")
        case .analysisFailed:
            return String(localized: "Analyse impossible : à vérifier vous-même")
        case .unknown:
            return String(localized: "Raison inconnue (version plus récente de LinkLens)")
        }
    }

    private func number(_ value: Double, _ locale: Locale, digits: Int = 0) -> String {
        value.formatted(.number.precision(.fractionLength(digits)).locale(locale))
    }

    /// « 5 % », never « 0 % »: the photo itself is among them.
    private func leastSharpShare(_ share: Double, _ locale: Locale) -> String {
        percent(max(0.01, (share * 100).rounded(.up) / 100), locale)
    }

    private func percent(_ share: Double, _ locale: Locale, digits: Int = 0) -> String {
        share.formatted(.percent.precision(.fractionLength(digits)).locale(locale))
    }
}
